<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Ubuntu Desktop</title>
<style>
  :root{
    --orange:#E95420;
    --aubergine:#2C001E;
    --purple:#77216F;
    --win-bg:#2b2b2b;
    --win-head:#3a3a3a;
    --text:#e8e6e3;
    --muted:#a8a29e;
    --border:#141414;
  }
  *{box-sizing:border-box;}
  html,body{margin:0;padding:0;height:100%;overflow:hidden;}
  body{
    font-family:Ubuntu, "Segoe UI", Cantarell, "DejaVu Sans", system-ui, sans-serif;
    color:var(--text);
    background:#1d1119;
    -webkit-font-smoothing:antialiased;
  }

  /* ---------- Desktop ---------- */
  #desktop{
    position:fixed;
    inset:0;
    width:100vw;
    height:100vh;
    overflow:hidden;
    background:
      radial-gradient(1200px 800px at 78% 18%, rgba(233,84,32,.32), transparent 60%),
      radial-gradient(900px 700px at 12% 88%, rgba(119,33,111,.45), transparent 62%),
      linear-gradient(160deg,#3a0c2e 0%, #2C001E 45%, #1a0a16 100%);
  }
  #desktop::after{
    /* subtle diagonal light streaks, pure CSS wallpaper */
    content:"";
    position:absolute;inset:0;
    background:
      repeating-linear-gradient(115deg, rgba(255,255,255,.028) 0 2px, transparent 2px 14px);
    pointer-events:none;
  }

  /* ---------- Top bar ---------- */
  #topbar{
    position:absolute;top:0;left:0;right:0;height:28px;
    background:rgba(15,8,13,.85);
    backdrop-filter:blur(6px);
    display:flex;align-items:center;justify-content:space-between;
    padding:0 12px;font-size:12.5px;color:#eee;z-index:9000;
    border-bottom:1px solid rgba(255,255,255,.06);
  }
  #topbar .tb-left{display:flex;gap:14px;align-items:center;font-weight:500;}
  #topbar .tb-right{display:flex;gap:12px;align-items:center;}
  .tb-dot{width:9px;height:9px;border-radius:50%;background:var(--orange);box-shadow:0 0 6px rgba(233,84,32,.8);}
  #clock{font-variant-numeric:tabular-nums;}

  /* ---------- Dock / taskbar ---------- */
  #taskbar{
    position:absolute;left:0;top:28px;bottom:0;width:68px;
    background:rgba(20,11,18,.78);
    backdrop-filter:blur(8px);
    border-right:1px solid rgba(255,255,255,.07);
    display:flex;flex-direction:column;align-items:center;gap:10px;
    padding:12px 0;z-index:8000;
  }
  .launcher{
    position:relative;
    width:48px;height:48px;border-radius:12px;border:none;cursor:pointer;
    display:flex;align-items:center;justify-content:center;
    color:#fff;font-size:11px;font-weight:700;letter-spacing:.3px;
    background:linear-gradient(180deg,#4b4b4b,#333);
    box-shadow:0 2px 6px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.12);
    transition:transform .12s ease, filter .12s ease;
    padding:0;
  }
  .launcher:hover{transform:translateY(-2px) scale(1.05);filter:brightness(1.15);}
  .launcher:active{transform:scale(.96);}
  #open-files{background:linear-gradient(180deg,#f0b040,#d98a17);}
  #open-notepad{background:linear-gradient(180deg,#7c5cbf,#5b3f9c);}
  .launcher .glyph{pointer-events:none;font-size:20px;line-height:1;}
  .launcher.running::before{
    content:"";position:absolute;left:-7px;top:50%;transform:translateY(-50%);
    width:3px;height:20px;border-radius:2px;background:var(--orange);
  }
  .launcher .tip{
    position:absolute;left:58px;top:50%;transform:translateY(-50%);
    background:rgba(0,0,0,.85);color:#fff;font-size:11.5px;font-weight:400;
    padding:4px 8px;border-radius:5px;white-space:nowrap;opacity:0;pointer-events:none;
    transition:opacity .12s ease;
  }
  .launcher:hover .tip{opacity:1;}
  .dock-sep{width:34px;height:1px;background:rgba(255,255,255,.15);margin:4px 0;}
  .dock-trash{background:linear-gradient(180deg,#5a5a5a,#3d3d3d);}

  /* ---------- Desktop icons ---------- */
  #desktop-icons{
    position:absolute;left:84px;top:44px;
    display:flex;flex-direction:column;gap:8px;z-index:10;
  }
  .desk-icon{
    width:96px;padding:8px 4px;border-radius:8px;text-align:center;
    cursor:pointer;user-select:none;font-size:12px;color:#fff;
    text-shadow:0 1px 3px rgba(0,0,0,.8);
  }
  .desk-icon:hover{background:rgba(255,255,255,.12);}
  .desk-icon .ico{
    display:block;width:44px;height:44px;margin:0 auto 6px;border-radius:10px;
    box-shadow:0 2px 5px rgba(0,0,0,.5);
    display:flex;align-items:center;justify-content:center;font-size:22px;
  }

  /* ---------- Windows ---------- */
  .window{
    position:absolute;
    display:none;
    flex-direction:column;
    min-width:360px;min-height:240px;
    background:var(--win-bg);
    border:1px solid #101010;
    border-radius:10px;
    box-shadow:0 18px 46px rgba(0,0,0,.6), 0 0 0 1px rgba(255,255,255,.05);
    overflow:hidden;
    z-index:100;
  }
  .titlebar{
    height:36px;flex:0 0 36px;
    background:linear-gradient(180deg,#454545,#353535);
    border-bottom:1px solid #1c1c1c;
    display:flex;align-items:center;justify-content:space-between;
    padding:0 8px 0 12px;cursor:grab;user-select:none;
  }
  .window.focused .titlebar{background:linear-gradient(180deg,#4f4f4f,#3b3b3b);}
  .titlebar .title{font-size:13px;font-weight:600;color:#f0eeec;display:flex;gap:8px;align-items:center;}
  .titlebar .title .tdot{width:10px;height:10px;border-radius:50%;}
  .win-btns{display:flex;gap:6px;}
  .win-btn{
    width:22px;height:22px;border-radius:50%;border:none;cursor:pointer;
    background:#5a5a5a;color:#eee;font-size:12px;line-height:1;
    display:flex;align-items:center;justify-content:center;
    padding:0;
  }
  .win-btn:hover{background:#6d6d6d;}
  .win-close:hover{background:var(--orange);color:#fff;}
  .win-body{flex:1 1 auto;display:flex;min-height:0;overflow:hidden;}
  .resize-handle{
    position:absolute;right:0;bottom:0;width:16px;height:16px;cursor:nwse-resize;
    background:linear-gradient(135deg,transparent 45%, rgba(255,255,255,.28) 45%, rgba(255,255,255,.28) 55%, transparent 55%);
  }

  /* ---------- Files app ---------- */
  #files-window{left:150px;top:80px;width:720px;height:460px;}
  .files-layout{flex:1;display:flex;min-height:0;}
  .files-side{
    width:170px;flex:0 0 170px;background:#242424;border-right:1px solid #141414;
    padding:10px 8px;overflow:auto;
  }
  .side-title{font-size:10.5px;text-transform:uppercase;letter-spacing:.9px;color:var(--muted);margin:6px 6px 6px;}
  .side-item{
    display:flex;align-items:center;gap:8px;
    padding:6px 8px;border-radius:6px;font-size:12.5px;cursor:pointer;color:#ddd;
  }
  .side-item:hover{background:#333;}
  .side-item.active{background:var(--orange);color:#fff;}
  .side-item .sq{width:12px;height:12px;border-radius:3px;background:#f0b040;flex:0 0 auto;}
  .files-main{flex:1;display:flex;flex-direction:column;min-width:0;min-height:0;}
  .files-toolbar{
    display:flex;align-items:center;gap:8px;padding:8px;background:#2f2f2f;
    border-bottom:1px solid #191919;
  }
  .tool-btn{
    height:28px;min-width:30px;padding:0 9px;border-radius:6px;border:1px solid #171717;
    background:linear-gradient(180deg,#4a4a4a,#3c3c3c);color:#eee;cursor:pointer;font-size:13px;
  }
  .tool-btn:hover{filter:brightness(1.18);}
  .tool-btn:disabled{opacity:.4;cursor:default;}
  #files-path{
    flex:1;min-width:0;height:28px;line-height:26px;
    background:#1e1e1e;border:1px solid #151515;border-radius:6px;
    padding:0 10px;font-family:"Ubuntu Mono",Consolas,monospace;font-size:13px;color:#ffd9c7;
    white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  }
  #files-list{
    flex:1;min-height:0;overflow:auto;padding:12px;
    display:grid;grid-template-columns:repeat(auto-fill,minmax(112px,1fr));
    gap:8px;align-content:start;background:#2b2b2b;
  }
  .fs-item{
    position:relative;
    padding:44px 6px 8px;border-radius:8px;text-align:center;
    font-size:12px;color:#eee;cursor:pointer;user-select:none;
    word-break:break-word;line-height:1.25;border:1px solid transparent;
  }
  .fs-item::before{
    content:"";position:absolute;top:8px;left:50%;transform:translateX(-50%);
    width:32px;height:26px;border-radius:4px 4px 5px 5px;
    background:linear-gradient(180deg,#f4bd57,#dc9520);
    box-shadow:inset 0 6px 0 rgba(255,255,255,.16), 0 1px 3px rgba(0,0,0,.5);
  }
  .fs-item.file::before{
    width:24px;height:30px;border-radius:3px;
    background:linear-gradient(180deg,#dcdcdc,#a9a9a9);
    box-shadow:inset -6px 6px 0 rgba(0,0,0,.12), 0 1px 3px rgba(0,0,0,.5);
  }
  .fs-item:hover{background:rgba(255,255,255,.08);}
  .fs-item.selected{background:rgba(233,84,32,.28);border-color:rgba(233,84,32,.7);}
  .files-status{
    flex:0 0 24px;height:24px;background:#242424;border-top:1px solid #171717;
    font-size:11.5px;color:var(--muted);display:flex;align-items:center;padding:0 10px;gap:12px;
  }

  /* ---------- Notepad ---------- */
  #notepad-window{left:520px;top:150px;width:600px;height:430px;}
  .np-layout{flex:1;display:flex;flex-direction:column;min-height:0;width:100%;}
  .np-bar{display:flex;align-items:stretch;background:#262626;border-bottom:1px solid #151515;}
  #tabs{
    flex:1;display:flex;align-items:stretch;gap:2px;overflow-x:auto;padding:4px 4px 0;
    min-width:0;
  }
  #tabs::-webkit-scrollbar{height:6px;}
  .tab{
    display:flex;align-items:center;gap:6px;
    max-width:190px;padding:6px 8px 6px 10px;
    background:#333;color:#cfcfcf;font-size:12.5px;
    border:1px solid #1a1a1a;border-bottom:none;
    border-radius:7px 7px 0 0;cursor:pointer;white-space:nowrap;user-select:none;
  }
  .tab:hover{background:#3d3d3d;}
  .tab.active{background:#300A24;color:#fff;border-color:#111;box-shadow:inset 0 2px 0 var(--orange);}
  .tab .tab-name{overflow:hidden;text-overflow:ellipsis;max-width:140px;}
  .tab .tab-x{
    width:16px;height:16px;border-radius:50%;flex:0 0 auto;
    display:flex;align-items:center;justify-content:center;
    font-size:12px;color:#bbb;
  }
  .tab .tab-x:hover{background:var(--orange);color:#fff;}
  #new-tab{
    flex:0 0 auto;margin:4px 6px;width:28px;height:26px;align-self:center;
    border:1px solid #171717;border-radius:6px;cursor:pointer;
    background:linear-gradient(180deg,#4a4a4a,#3a3a3a);color:#fff;font-size:16px;line-height:1;
    padding:0;
  }
  #new-tab:hover{background:var(--orange);}
  #editor{
    flex:1;min-height:0;width:100%;resize:none;border:none;outline:none;
    background:#300A24;color:#f2eeea;
    font-family:"Ubuntu Mono",Consolas,"DejaVu Sans Mono",monospace;
    font-size:14px;line-height:1.5;padding:12px 14px;
  }
  .np-status{
    flex:0 0 24px;height:24px;background:#242424;border-top:1px solid #171717;
    font-size:11.5px;color:var(--muted);display:flex;align-items:center;justify-content:space-between;
    padding:0 10px;
  }
  ::-webkit-scrollbar{width:11px;height:11px;}
  ::-webkit-scrollbar-track{background:#232323;}
  ::-webkit-scrollbar-thumb{background:#555;border-radius:6px;border:2px solid #232323;}
  ::-webkit-scrollbar-thumb:hover{background:#6d6d6d;}
</style>
