      <span class="ico" style="background:linear-gradient(180deg,#7c5cbf,#5b3f9c)">✎</span>
      Notepad
    </div>
  </div>

  <!-- ============ FILES WINDOW ============ -->
  <div class="window" id="files-window" data-app="files">
    <div class="titlebar" data-drag="1">
      <div class="title"><span class="tdot" style="background:#f0b040"></span> Files</div>
      <div class="win-btns">
        <button class="win-btn win-min" title="Minimize">–</button>
        <button class="win-btn win-max" title="Maximize">▢</button>
        <button class="win-btn win-close" title="Close">✕</button>
      </div>
    </div>
    <div class="win-body">
      <div class="files-layout">
        <div class="files-side">
          <div class="side-title">Places</div>
          <div class="side-item" data-goto="/home/user"><span class="sq"></span>Home</div>
          <div class="side-item" data-goto="/home/user/Documents"><span class="sq"></span>Documents</div>
          <div class="side-item" data-goto="/home/user/Downloads"><span class="sq"></span>Downloads</div>
          <div class="side-item" data-goto="/home/user/Pictures"><span class="sq"></span>Pictures</div>
          <div class="side-title">System</div>
          <div class="side-item" data-goto="/"><span class="sq" style="background:#bbb"></span>Filesystem</div>
          <div class="side-item" data-goto="/etc"><span class="sq" style="background:#bbb"></span>etc</div>
          <div class="side-item" data-goto="/var/log"><span class="sq" style="background:#bbb"></span>var/log</div>
        </div>
        <div class="files-main">
          <div class="files-toolbar">
            <button class="tool-btn" id="files-back" title="Back">◀</button>
            <button class="tool-btn" id="files-up" title="Parent folder">▲</button>
            <button class="tool-btn" id="files-home" title="Home folder">⌂</button>
            <div id="files-path">/</div>
          </div>
          <div id="files-list"></div>
          <div class="files-status">
            <span id="files-count">0 items</span>
            <span id="files-hint">Double-click a folder to open it</span>
          </div>
        </div>
      </div>
    </div>
    <div class="resize-handle" data-resize="1"></div>
  </div>

  <!-- ============ NOTEPAD WINDOW ============ -->
  <div class="window" id="notepad-window" data-app="notepad">
    <div class="titlebar" data-drag="1">
      <div class="title"><span class="tdot" style="background:#7c5cbf"></span> Notepad</div>
      <div class="win-btns">
        <button class="win-btn win-min" title="Minimize">–</button>
        <button class="win-btn win-max" title="Maximize">▢</button>
        <button class="win-btn win-close" title="Close">✕</button>
      </div>
    </div>
    <div class="win-body">
      <div class="np-layout">
        <div class="np-bar">
          <div id="tabs"></div>
          <button id="new-tab" title="New tab">+</button>
        </div>
        <textarea id="editor" spellcheck="false" placeholder="Type here…"></textarea>
        <div class="np-status">
          <span id="np-info">—</span>
          <span id="np-saved">saved to localStorage</span>
        </div>
      </div>
    </div>
    <div class="resize-handle" data-resize="1"></div>
  </div>

</div>

