/* =====================================================================
   Window management: focus, drag, resize, open/close
   ===================================================================== */
var desktop = document.getElementById("desktop");
var zTop = 100;

function windows(){ return Array.prototype.slice.call(document.querySelectorAll(".window")); }

function focusWin(win){
  zTop++;
  win.style.zIndex = zTop;
  windows().forEach(function(w){ w.classList.toggle("focused", w === win); });
  var name = win.id === "files-window" ? "Files" : "Notepad";
  document.getElementById("active-app").textContent = name;
}

function ensureGeometry(win){
  var vw = window.innerWidth, vh = window.innerHeight;
  var w = Math.max(360, Math.min(parseInt(win.style.width,10) || win.offsetWidth || 640, Math.max(360, vw - 90)));
  var h = Math.max(240, Math.min(parseInt(win.style.height,10) || win.offsetHeight || 440, Math.max(240, vh - 60)));
  win.style.width = w + "px";
  win.style.height = h + "px";
  var left = parseInt(win.style.left,10); if (isNaN(left)) left = 120;
  var top = parseInt(win.style.top,10); if (isNaN(top)) top = 70;
  left = Math.max(74, Math.min(left, Math.max(74, vw - w - 6)));
  top = Math.max(32, Math.min(top, Math.max(32, vh - h - 6)));
  win.style.left = left + "px";
  win.style.top = top + "px";
}

function openWin(win){
  win.style.display = "flex";
  ensureGeometry(win);
  focusWin(win);
  updateDock();
  if (win.id === "notepad-window") { setTimeout(function(){ try{ editor.focus(); }catch(e){} }, 0); }
}
function closeWin(win){
  win.style.display = "none";
  win.classList.remove("focused");
  updateDock();
  var visible = windows().filter(function(w){ return w.style.display !== "none"; });
  document.getElementById("active-app").textContent = visible.length ? (visible[visible.length-1].id === "files-window" ? "Files" : "Notepad") : "Desktop";
}
function isOpen(win){ return win.style.display !== "none" && win.offsetParent !== null; }

function updateDock(){
  document.getElementById("open-files").classList.toggle("running", isOpen(filesWin));
  document.getElementById("open-notepad").classList.toggle("running", isOpen(npWin));
}

var filesWin = document.getElementById("files-window");
var npWin = document.getElementById("notepad-window");

/* launchers */
document.getElementById("open-files").addEventListener("click", function(){ openWin(filesWin); });
document.getElementById("open-notepad").addEventListener("click", function(){ openWin(npWin); });
