/* per-window controls */
windows().forEach(function(win){
  win.addEventListener("mousedown", function(){ focusWin(win); }, true);

  win.querySelector(".win-close").addEventListener("click", function(e){
    e.stopPropagation();
    closeWin(win);
  });
  win.querySelector(".win-min").addEventListener("click", function(e){
    e.stopPropagation();
    win.style.display = "none";
    updateDock();
  });
  win.querySelector(".win-max").addEventListener("click", function(e){
    e.stopPropagation();
    if (win.dataset.maxed === "1"){
      win.style.left = win.dataset.rl; win.style.top = win.dataset.rt;
      win.style.width = win.dataset.rw; win.style.height = win.dataset.rh;
      win.dataset.maxed = "0";
    } else {
      win.dataset.rl = win.style.left; win.dataset.rt = win.style.top;
      win.dataset.rw = win.style.width; win.dataset.rh = win.style.height;
      win.style.left = "68px"; win.style.top = "28px";
      win.style.width = (window.innerWidth - 68) + "px";
      win.style.height = (window.innerHeight - 28) + "px";
      win.dataset.maxed = "1";
    }
  });

  /* dragging */
  var bar = win.querySelector(".titlebar");
  var drag = null;
  bar.addEventListener("mousedown", function(e){
    if (e.target.closest(".win-btn")) return;
    focusWin(win);
    if (win.dataset.maxed === "1") return;
    drag = { x:e.clientX, y:e.clientY, l:parseInt(win.style.left,10)||win.offsetLeft, t:parseInt(win.style.top,10)||win.offsetTop };
    bar.style.cursor = "grabbing";
    e.preventDefault();
  });

  /* resizing */
  var handle = win.querySelector(".resize-handle");
  var rez = null;
  handle.addEventListener("mousedown", function(e){
    focusWin(win);
    rez = { x:e.clientX, y:e.clientY, w:win.offsetWidth, h:win.offsetHeight };
    e.preventDefault(); e.stopPropagation();
  });

  document.addEventListener("mousemove", function(e){
    if (drag){
      var nl = drag.l + (e.clientX - drag.x);
      var nt = drag.t + (e.clientY - drag.y);
      nl = Math.max(-win.offsetWidth + 90, Math.min(nl, window.innerWidth - 60));
      nt = Math.max(28, Math.min(nt, window.innerHeight - 40));
      win.style.left = nl + "px";
      win.style.top = nt + "px";
    }
    if (rez){
      win.style.width = Math.max(360, rez.w + (e.clientX - rez.x)) + "px";
      win.style.height = Math.max(240, rez.h + (e.clientY - rez.y)) + "px";
    }
  });
  document.addEventListener("mouseup", function(){
    if (drag){ drag = null; bar.style.cursor = "grab"; }
    rez = null;
  });
});

/* =====================================================================
   Files app
   ===================================================================== */
var pathEl = document.getElementById("files-path");
var listEl = document.getElementById("files-list");
var countEl = document.getElementById("files-count");
var hintEl = document.getElementById("files-hint");
var cwd = [];              // array of path segments
var history = [];          // navigation history (arrays)

function pathString(segs){ return "/" + segs.join("/"); }

function resolve(segs){
  var node = FS;
  for (var i=0;i<segs.length;i++){
    if (!node || node.type !== "dir") return null;
    node = node.children[segs[i]];
  }
  return node || null;
}

function render(){
  pathEl.textContent = pathString(cwd);
  pathEl.title = pathString(cwd);
  var node = resolve(cwd);
  listEl.innerHTML = "";
  if (!node || node.type !== "dir"){
    countEl.textContent = "0 items";
    return;
  }
  var names = Object.keys(node.children);
  names.sort(function(a,b){
    var da = node.children[a].type === "dir", db = node.children[b].type === "dir";
    if (da !== db) return da ? -1 : 1;
    return a.toLowerCase() < b.toLowerCase() ? -1 : (a.toLowerCase() > b.toLowerCase() ? 1 : 0);
  });
  names.forEach(function(name){
    var child = node.children[name];
    var el = document.createElement("div");
    el.className = "fs-item" + (child.type === "dir" ? " dir" : " file");
    el.textContent = name;
    el.setAttribute("data-name", name);
    el.setAttribute("data-type", child.type);
    el.title = (child.type === "dir" ? "Folder: " : "File: ") + pathString(cwd.concat(name));
    el.tabIndex = 0;
    listEl.appendChild(el);
  });
  countEl.textContent = names.length + (names.length === 1 ? " item" : " items");
  document.querySelectorAll(".side-item").forEach(function(s){
    s.classList.toggle("active", s.getAttribute("data-goto") === pathString(cwd));
  });
  var upBtn = document.getElementById("files-up");
  upBtn.disabled = cwd.length === 0;
  document.getElementById("files-back").disabled = history.length === 0;
}

function navigate(segs, pushHistory){
  var node = resolve(segs);
  if (!node || node.type !== "dir") return;
  if (pushHistory !== false) history.push(cwd.slice());
  cwd = segs.slice();
  render();
}

function goPath(str){
  var segs = str.split("/").filter(function(s){ return s.length; });
  navigate(segs);
}

listEl.addEventListener("click", function(e){
  var item = e.target.closest(".fs-item");
  listEl.querySelectorAll(".fs-item.selected").forEach(function(x){ x.classList.remove("selected"); });
  if (!item) return;
  item.classList.add("selected");
  hintEl.textContent = (item.getAttribute("data-type") === "dir" ? "Folder " : "File ") + item.textContent;
});

listEl.addEventListener("dblclick", function(e){
  var item = e.target.closest(".fs-item");
  if (!item) return;
  var name = item.getAttribute("data-name");
  var target = cwd.concat(name);
  var node = resolve(target);
  if (node && node.type === "dir"){
    navigate(target);
    hintEl.textContent = "Opened " + pathString(target);
  } else if (node){
    /* open the file in Notepad */
    openWin(npWin);
    createTab(name, node.content || "");
    hintEl.textContent = "Opened " + name + " in Notepad";
  }
});

/* keyboard: Enter opens selected item */
listEl.addEventListener("keydown", function(e){
  if (e.key === "Enter"){
    var sel = listEl.querySelector(".fs-item.selected");
    if (sel) sel.dispatchEvent(new MouseEvent("dblclick", {bubbles:true}));
  }
});

document.getElementById("files-up").addEventListener("click", function(){
  if (cwd.length === 0){ hintEl.textContent = "Already at filesystem root"; return; }
  var parent = cwd.slice(0, cwd.length - 1);
  navigate(parent);
  hintEl.textContent = "Moved up to " + pathString(parent);
});
document.getElementById("files-back").addEventListener("click", function(){
  if (!history.length) return;
  var prev = history.pop();
  cwd = prev;
  render();
});
document.getElementById("files-home").addEventListener("click", function(){ goPath("/home/user"); });
document.querySelectorAll(".side-item").forEach(function(s){
  s.addEventListener("click", function(){ goPath(s.getAttribute("data-goto")); });
});

render();

/* =====================================================================
   Notepad app (tabbed + localStorage persistence)
   ===================================================================== */
var STORE_KEY = "ubuntu-notepad-state-v1";
var tabsEl = document.getElementById("tabs");
var editor = document.getElementById("editor");
var npInfo = document.getElementById("np-info");
var npSaved = document.getElementById("np-saved");

var state = { tabs: [], activeId: null, counter: 0 };

function saveState(){
  try {
    localStorage.setItem(STORE_KEY, JSON.stringify(state));
    npSaved.textContent = "saved to localStorage";
  } catch(e){
    npSaved.textContent = "could not save (storage unavailable)";
  }
}

function loadState(){
  var raw = null;
  try { raw = localStorage.getItem(STORE_KEY); } catch(e){ raw = null; }
  if (raw){
    try {
      var parsed = JSON.parse(raw);
      if (parsed && Array.isArray(parsed.tabs) && parsed.tabs.length){
        state.tabs = parsed.tabs.map(function(t, i){
          return {
            id: String(t.id != null ? t.id : ("t" + i)),
            name: String(t.name != null ? t.name : ("Untitled " + (i+1))),
            content: String(t.content != null ? t.content : "")
          };
        });
        state.counter = typeof parsed.counter === "number" ? parsed.counter : state.tabs.length;
        state.activeId = parsed.activeId && state.tabs.some(function(t){ return t.id === parsed.activeId; })
          ? parsed.activeId : state.tabs[0].id;
        return;
      }
    } catch(e){ /* fall through to defaults */ }
  }
  state.tabs = [];
  state.counter = 0;
  state.activeId = null;
  createTab("Welcome", "Welcome to Notepad on Ubuntu!\n\n• Click + to open a new tab.\n• Click a tab to switch to it.\n• Everything you type is stored in localStorage,\n  so it survives closing this window and reloading the page.\n", false);
}

function newId(){ return "t" + Date.now().toString(36) + Math.random().toString(36).slice(2,7); }

function activeTab(){
  for (var i=0;i<state.tabs.length;i++) if (state.tabs[i].id === state.activeId) return state.tabs[i];
  return null;
}

function createTab(name, content, save){
  state.counter++;
  var tab = {
    id: newId(),
    name: name || ("Untitled " + state.counter),
    content: content || ""
  };
  state.tabs.push(tab);
  state.activeId = tab.id;
  renderTabs();
  if (save !== false) saveState();
  try { editor.focus(); } catch(e){}
  return tab;
}

function closeTab(id){
  var idx = -1;
  for (var i=0;i<state.tabs.length;i++) if (state.tabs[i].id === id) idx = i;
  if (idx < 0) return;
  state.tabs.splice(idx, 1);
  if (!state.tabs.length){
    createTab(null, "", false);
  } else if (state.activeId === id){
    state.activeId = state.tabs[Math.max(0, idx - 1)].id;
  }
  renderTabs();
  saveState();
}

function selectTab(id){
  if (state.activeId === id) return;
  var t = activeTab();
  if (t) t.content = editor.value;
  state.activeId = id;
  renderTabs();
  saveState();
  try { editor.focus(); } catch(e){}
}

function renderTabs(){
  tabsEl.innerHTML = "";
  state.tabs.forEach(function(t){
    var el = document.createElement("div");
    el.className = "tab" + (t.id === state.activeId ? " active" : "");
    el.setAttribute("data-id", t.id);
    el.title = t.name + " (double-click to rename)";

    var nameEl = document.createElement("span");
    nameEl.className = "tab-name";
    nameEl.textContent = t.name;
    el.appendChild(nameEl);

    var x = document.createElement("span");
    x.className = "tab-x";
    x.textContent = "×";
    x.title = "Close tab";
    el.appendChild(x);

    tabsEl.appendChild(el);
  });

  var t = activeTab();
  editor.value = t ? t.content : "";
  editor.disabled = !t;
  updateInfo();
}

function updateInfo(){
  var t = activeTab();
  if (!t){ npInfo.textContent = "—"; return; }
  var text = editor.value;
  var lines = text.length ? text.split("\n").length : 1;
  var words = text.trim() ? text.trim().split(/\s+/).length : 0;
  npInfo.textContent = t.name + "  •  " + lines + " lines, " + words + " words, " + text.length + " chars  •  " +
    state.tabs.length + (state.tabs.length === 1 ? " tab" : " tabs");
}

tabsEl.addEventListener("click", function(e){
  var tabEl = e.target.closest(".tab");
  if (!tabEl) return;
  var id = tabEl.getAttribute("data-id");
  if (e.target.classList.contains("tab-x")){
    e.stopPropagation();
    closeTab(id);
    return;
  }
  selectTab(id);
});

tabsEl.addEventListener("dblclick", function(e){
  var tabEl = e.target.closest(".tab");
  if (!tabEl || e.target.classList.contains("tab-x")) return;
  var id = tabEl.getAttribute("data-id");
  var t = null;
  state.tabs.forEach(function(x){ if (x.id === id) t = x; });
  if (!t) return;
  var name = window.prompt("Rename tab:", t.name);
  if (name !== null){
    name = name.trim();
    if (name) { t.name = name; renderTabs(); saveState(); }
  }
});

document.getElementById("new-tab").addEventListener("click", function(){
  var t = activeTab();
  if (t) t.content = editor.value;
  createTab(null, "");
});

var saveTimer = null;
editor.addEventListener("input", function(){
  var t = activeTab();
  if (!t) return;
  t.content = editor.value;
  updateInfo();
  npSaved.textContent = "saving…";
  clearTimeout(saveTimer);
  saveTimer = setTimeout(saveState, 180);
});
editor.addEventListener("blur", function(){
  var t = activeTab();
  if (t) { t.content = editor.value; saveState(); }
});
window.addEventListener("beforeunload", function(){
  var t = activeTab();
  if (t) t.content = editor.value;
  saveState();
});

/* tab key inserts a tab character instead of leaving the editor */
editor.addEventListener("keydown", function(e){
  if (e.key === "Tab"){
    e.preventDefault();
    var s = editor.selectionStart, en = editor.selectionEnd;
    editor.value = editor.value.slice(0, s) + "\t" + editor.value.slice(en);
    editor.selectionStart = editor.selectionEnd = s + 1;
    editor.dispatchEvent(new Event("input"));
  }
});

loadState();
